'use strict';
(() => {
const D = window.STUDY_DATA;
const root = document.getElementById('app');
if (!D) { root.innerHTML = '<p class="loading">题库未能加载，请刷新页面。</p>'; return; }
const KEY = 'ruc802.practice.v1';
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.getElementById('main')?.focus();});
const all = D.subjects.flatMap(s => s.questions.map(q => ({...q, subject:s.key, subjectName:s.name})));
const byId = Object.assign(Object.create(null),Object.fromEntries(all.map(q => [q.id,q])));
const sub = Object.fromEntries(D.subjects.map(s => [s.key,s]));
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nowDate = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const validDate = d => /^\d{4}-\d{2}-\d{2}$/.test(d) && Number.isFinite(Date.parse(d+'T00:00:00Z')) && new Date(d+'T00:00:00Z').toISOString().slice(0,10)===d;
const dayDelta = (a,b) => Math.floor((Date.parse(a+'T00:00:00Z')-Date.parse(b+'T00:00:00Z'))/86400000);
const dateFor = n => new Date(Date.parse(state.start+'T00:00:00Z')+(n-1)*86400000).toISOString().slice(0,10);
const uid = () => Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9);
let storageOK=true, toastTimer, filter={subject:'micro',group:'all',status:'all',search:'',page:1}, selectedDay;
const readingDefaults=()=>({size:19,face:'serif',focus:false});
const fresh = () => ({version:1,start:D.plan.start,records:[],drafts:{},favorites:[],session:null,reading:readingDefaults()});
function cleanWork(w,qid,records){return {seconds:Math.max(0,Math.min(604800,Number(w?.seconds)||0)),revealed:!!w?.revealed,hint:!!w?.hint,ratingId:records.some(r=>r.id===w?.ratingId&&r.qid===qid)?w.ratingId:null};}
function rememberQuestion(){const s=state.session;if(s){s.work??={};s.work[s.ids[s.index]]={seconds:elapsed(),revealed:s.revealed,hint:s.hint,ratingId:s.ratingId};}}
function applyReading(){document.documentElement.style.setProperty('--reading-size',state.reading.size+'px');document.body.dataset.face=state.reading.face;document.body.classList.toggle('reading-focus',route()==='practice'&&state.reading.focus);}
function readingBar(){return `<div class="reading-bar" aria-label="阅读设置"><div class="reading-size" role="group" aria-label="字号">${[[17,'小'],[19,'标准'],[21,'大']].map(([size,label])=>`<button data-action="font-size" data-size="${size}" aria-label="${label}字号" aria-pressed="${state.reading.size===size}" class="${state.reading.size===size?'selected':''}">${label}</button>`).join('')}</div><label><span class="visually-hidden">正文字体</span><select id="reading-face"><option value="serif" ${state.reading.face==='serif'?'selected':''}>宋体阅读</option><option value="sans" ${state.reading.face==='sans'?'selected':''}>黑体阅读</option></select></label><button class="focus-toggle" data-action="focus" aria-pressed="${state.reading.focus}">${state.reading.focus?'退出专注':'专注阅读'}</button></div>`;}
function readingLocation(id){document.getElementById(id)?.scrollIntoView({block:'start'});}
function validate(input) {
 if (!input || input.version!==1 || !validDate(input.start) || !Array.isArray(input.records) || input.records.length>20000 || !Array.isArray(input.favorites) || !input.drafts || typeof input.drafts!=='object') throw new Error('备份格式不正确，请选择本网站导出的JSON文件。');
 const result=fresh(); result.start=input.start;
 if(input.reading)result.reading={size:[17,19,21].includes(input.reading.size)?input.reading.size:19,face:input.reading.face==='sans'?'sans':'serif',focus:!!input.reading.focus};
 result.records=input.records.map(r=>{
  if (!r || !byId[r.qid] || typeof r.id!=='string' || r.id.length>100 || ![0,1,2].includes(r.rating) || !Number.isFinite(r.at) || r.at<0 || r.at>1e14 || !Number.isFinite(r.seconds) || r.seconds<0 || r.seconds>604800 || (r.day!==null && (!Number.isInteger(r.day)||r.day<1||r.day>50))) throw new Error('备份中存在无效练习记录，未导入。');
  return {id:r.id,qid:r.qid,rating:r.rating,at:r.at,updatedAt:Number.isFinite(r.updatedAt)&&r.updatedAt>=r.at&&r.updatedAt<=1e14?r.updatedAt:r.at,seconds:r.seconds,day:r.day};
 });
 result.records=[...new Map(result.records.map(r=>[r.id,r])).values()].sort((a,b)=>a.at-b.at);
 result.favorites=[...new Set(input.favorites.filter(id=>typeof id==='string'&&byId[id]))];
 for(const [id,text] of Object.entries(input.drafts)){if(byId[id]&&typeof text==='string'&&text.length<=100000) result.drafts[id]=text;else throw new Error('备份中的草稿无效，未导入。');}
 if(input.session && Array.isArray(input.session.ids) && input.session.ids.length && input.session.ids.length<=300 && input.session.ids.every(id=>byId[id]) && Number.isInteger(input.session.index) && input.session.index>=0 && input.session.index<input.session.ids.length){
  const s=input.session; result.session={ids:[...new Set(s.ids)],index:s.index,mode:String(s.mode||'自由练习').slice(0,40),day:Number.isInteger(s.day)&&s.day>=1&&s.day<=50?s.day:null,seconds:Math.max(0,Math.min(604800,Number(s.seconds)||0)),startedAt:null,revealed:!!s.revealed,hint:!!s.hint,ratingId:typeof s.ratingId==='string'?s.ratingId:null};
  if(result.session.index>=result.session.ids.length) result.session.index=0;
  result.session.work=Object.create(null);
  for(const id of result.session.ids){if(input.session.work?.[id])result.session.work[id]=cleanWork(input.session.work[id],id,result.records);}
  Object.assign(result.session,cleanWork(result.session,result.session.ids[result.session.index],result.records));
 }
 return result;
}
let state;
try { const raw=localStorage.getItem(KEY); state=raw?validate(JSON.parse(raw)):fresh(); } catch(e) { state=fresh(); storageOK=false; }
function save(){rememberQuestion();try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;document.querySelector('.local-status')?.replaceChildren(document.createTextNode('未能保存，请导出备份'));} }
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}
const latest = id => [...state.records].reverse().find(r=>r.qid===id);
const gradeText = r => r===2?'会做':r===1?'不熟':'不会';
const gradeClass = r => r===2?'done':r===1?'weak':'wrong';
function todayDay(){return Math.max(1,Math.min(50,dayDelta(nowDate(),state.start)+1));}
selectedDay=todayDay();
function dayRecord(id,day){return [...state.records].reverse().find(r=>r.qid===id&&r.day===day);}
function icon(name){const paths={today:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-14 5h3m4 0h3"/>',bank:'<path d="M4 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4zM14 5h6v14h-6"/>',wrong:'<path d="M8 3h8l5 5v13H3V3h5m5 0v6h7M8 12l8 6m0-6-8 6"/>',favorites:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',materials:'<path d="M4 3h10l6 6v12H4zM14 3v6h6M8 13h8m-8 4h6"/>',history:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',settings:'<path d="M4 7h16M4 17h16M9 4v6m7 4v6"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.bank}</svg>`;}
const pages={today:'今日计划',bank:'全部题库',wrong:'错题复做',favorites:'我的收藏',materials:'基础回查',history:'练习记录',settings:'设置与备份',practice:'正在练习'};
function route(){const key=location.hash.slice(1)||'today';return Object.hasOwn(pages,key)?key:'today';}
function shell(content,page){const wrong=all.filter(q=>{let r=latest(q.id);return r&&r.rating<2;}).length;
 const items=['today','bank','wrong','favorites','materials','history','settings'];
 root.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#today"><img src="icon.svg" alt=""><span>802练习室</span></a><nav class="nav" aria-label="主导航">${items.map(k=>`<a href="#${k}" ${page===k?'class="active" aria-current="page"':''}>${icon(k)}${pages[k]}${k==='wrong'&&wrong?`<span class="count">${wrong}</span>`:''}${k==='favorites'&&state.favorites.length?`<span class="count">${state.favorites.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-foot"><p>人大经济学综合</p><p>三科各100题，50天五轮练习。</p><p>记录保存在当前浏览器。<br><a href="#settings">导出备份，带走进度</a></p></div></aside><main id="main" class="main" tabindex="-1"><div class="topbar"><div class="breadcrumb">人大802 / ${pages[page]}</div><span class="local-status">${storageOK?'进度保存在此浏览器':'未能保存，请导出备份'}</span></div>${!storageOK?'<div class="notice">浏览器未能读取或保存记录。请先在“设置与备份”导出当前记录，避免关闭后丢失。</div>':''}${content}</main></div>`;
 applyReading();
}
function chip(id,record,attrs=''){return `<button class="qchip ${record?gradeClass(record.rating):''}" ${attrs} title="${esc(byId[id].title)}${record?' / '+gradeText(record.rating):''}">${id}</button>`;}
function home(){const day=D.plan.days[selectedDay-1];const done=all.filter(q=>dayRecord(q.id,selectedDay)).length;const distinct=new Set(state.records.map(r=>r.qid)).size;const rawDay=dayDelta(nowDate(),state.start)+1;
 const timeMessage=rawDay<1?'计划尚未开始，可先做第1天。':rawDay>50?'已超过50天，可选任意一天继续复做。':`今天是计划第${todayDay()}天。`;
 shell(`<div class="page-heading"><div><h1>把今天的题，认真做完。</h1><p>先闭卷作答，再对照解答。三科各10道，连续小问算一道整题。</p></div>${state.session?'<button class="btn ink" data-action="resume">继续上次练习</button>':''}</div><section class="paper"><div class="today-head"><div class="day-select"><div><div class="day-number">第 ${selectedDay} 天<span>/ 50天</span></div><div class="phase">${esc(day.phase)} · 第${Math.ceil(selectedDay/10)}轮</div></div><label><span class="visually-hidden">选择计划日</span><button class="day-step" data-action="day-prev" aria-label="上一计划日" ${selectedDay===1?'disabled':''}>‹</button><select id="day-select" aria-label="选择计划日">${D.plan.days.map(d=>`<option value="${d.day}" ${d.day===selectedDay?'selected':''}>第${d.day}天</option>`).join('')}</select><button class="day-step" data-action="day-next" aria-label="下一计划日" ${selectedDay===50?'disabled':''}>›</button></label></div><div class="date-control"><span>${dateFor(selectedDay)}</span><button class="btn flat" data-action="today">回到今天</button></div></div>${D.subjects.map((s,i)=>{const ids=day[s.key+'_refs'];const count=ids.filter(id=>dayRecord(id,selectedDay)).length;return `<div class="subject-row"><div><div class="subject-title">${s.name}</div><div class="subject-topic">${selectedDay<=10?esc(byId[ids[0]].group_title):'跨组整题复做'}</div></div><div class="subject-pills">${ids.map(id=>chip(id,dayRecord(id,selectedDay),`data-action="day-question" data-id="${id}" data-sub="${s.key}"`)).join('')}</div><div class="row-action"><div class="small muted">已作答 ${count}/10 · 约${day.minutes[i]}分钟</div><button class="btn ${count<10?'primary':''}" data-action="start-day" data-sub="${s.key}">${count===10?'再做一遍':'开始练习'}</button></div></div>`;}).join('')}<div class="study-footer"><span>当天已自评 ${done}/30题。另留60分钟订正；建议总用时约${(day.planned_minutes/60).toFixed(1)}小时，休息另计。</span><a href="#settings">调整开始日期</a></div></section><div class="under-grid"><section class="quiet-panel"><h3>这一轮，练到哪里了</h3><div class="progress-summary"><span>累计接触 ${distinct}/300道独立题</span><span>已自评 ${state.records.length}次</span></div><div class="progress-line"><i style="width:${distinct/3}%"></i></div><p>每科100题各做5轮，50天共1500次作答。题号重复表示复做，不算新增题。</p></section><section class="quiet-panel"><h3>复盘时，抓住一个断点</h3><p>条件哪里漏了，推导哪里断了，论证哪里没接上。把“不熟”和“不会”的题留到错题复做。</p><p>${timeMessage}</p><a href="#wrong" class="small">打开错题复做</a></section></div>`,'today');
}
function filtered(page){let result=all.filter(q=>q.subject===filter.subject);
 if(page==='wrong') result=result.filter(q=>{let r=latest(q.id);return r&&r.rating<2;});
 if(page==='favorites')result=result.filter(q=>state.favorites.includes(q.id));
 if(filter.group!=='all')result=result.filter(q=>q.group===filter.group);
 if(filter.status!=='all')result=result.filter(q=>{const r=latest(q.id);return filter.status==='new'?!r:filter.status==='good'?r?.rating===2:r&&r.rating<2;});
 const key=filter.search.trim().toLowerCase();if(key)result=result.filter(q=>(q.id+' '+q.title+' '+q.group_title+' '+q.prompt_md).toLowerCase().includes(key));return result;
}
function library(page){const list=filtered(page);const size=20;filter.page=Math.min(filter.page,Math.max(1,Math.ceil(list.length/size)));const view=list.slice((filter.page-1)*size,filter.page*size);const subtitle={bank:'按专题找题，也可以随机抽取10道。完整解答在作答页中查看。',wrong:'按最近一次自评收集“不熟”和“不会”。复做后选“会做”，即可移出。',favorites:'把值得反复推敲的题留在这里。收藏与错题分别记录。'}[page];
 shell(`<div class="page-heading"><div><h1>${pages[page]}</h1><p>${subtitle}</p></div><button class="btn primary" data-action="random" ${list.length?'':'disabled'}>随机练${Math.min(10,list.length)||10}题</button></div><div class="tabs" role="group" aria-label="选择科目">${D.subjects.map(s=>`<button class="tab ${s.key===filter.subject?'active':''}" data-action="subject" data-sub="${s.key}" aria-pressed="${s.key===filter.subject}">${s.name}</button>`).join('')}</div><div class="toolbar"><label class="search"><span class="visually-hidden">搜索题号、题名或题干</span><input id="search" type="search" placeholder="搜索题号、题名或题干" value="${esc(filter.search)}"></label><label><span class="visually-hidden">筛选专题</span><select id="group-filter"><option value="all">全部专题</option>${sub[filter.subject].groups.map(g=>`<option value="${g.id}" ${filter.group===g.id?'selected':''}>${g.id} ${esc(g.title)}</option>`).join('')}</select></label><label><span class="visually-hidden">筛选掌握状态</span><select id="status-filter">${[['all','全部状态'],['new','未作答'],['weak','不熟 / 不会'],['good','会做']].map(([v,t])=>`<option value="${v}" ${filter.status===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="bank-meta"><span>找到 ${list.length} 道题${filter.group!=='all'?' · 本专题10道':''}</span><button class="btn flat" data-action="start-filter" ${list.length?'':'disabled'}>${filter.group!=='all'?'练习本专题':'按顺序练习'}</button></div><section class="paper">${view.length?`<ul class="question-list">${view.map(q=>{const r=latest(q.id);return `<li class="question-row"><span class="qid">${q.id}</span><div><h3>${esc(q.title)}${r?`<span class="status-pill ${r.rating===2?'good':'bad'}">${gradeText(r.rating)}</span>`:''}</h3><p>${esc(q.group_title)} · 建议${q.minutes}分钟 · ${esc(q.kind)}</p></div><div class="row-buttons"><button class="star ${state.favorites.includes(q.id)?'on':''}" data-action="favorite" data-id="${q.id}" aria-label="${state.favorites.includes(q.id)?'取消收藏':'收藏'} ${q.id}" aria-pressed="${state.favorites.includes(q.id)}">${state.favorites.includes(q.id)?'★':'☆'}</button><button class="btn" data-action="single" data-id="${q.id}">开始作答</button></div></li>`;}).join('')}</ul>`:`<div class="empty"><h2>${page==='wrong'?'这里暂时没有错题':page==='favorites'?'还没有收藏的题':'没有找到符合条件的题'}</h2><p>${filter.search||filter.group!=='all'||filter.status!=='all'?'试试清除搜索或更换筛选条件。':'完成作答后可以自评、收藏，记录会出现在这里。'}</p><button class="btn" data-action="clear-filter">清除筛选</button></div>`}</section>${list.length>size?`<div class="pagination"><button class="btn" data-action="prev-page" ${filter.page===1?'disabled':''}>上一页</button><span class="small muted">第${filter.page}/${Math.ceil(list.length/size)}页</span><button class="btn" data-action="next-page" ${filter.page*size>=list.length?'disabled':''}>下一页</button></div>`:''}`,page);
}
function elapsed(){const s=state.session;return s?Math.floor(s.seconds+(s.startedAt?(Date.now()-s.startedAt)/1000:0)):0;}
function pause(){const s=state.session;if(s?.startedAt){s.seconds=elapsed();s.startedAt=null;save();}}
function flushDraft(){const el=document.getElementById('draft');if(el&&state.session){state.drafts[state.session.ids[state.session.index]]=el.value;save();}}
function navigate(hash){flushDraft();pause();if(location.hash==='#'+hash)render();else location.hash=hash;}
function start(ids,mode,day=null,index=0){flushDraft();pause();state.session={ids:[...ids],index,mode,day,seconds:0,startedAt:null,revealed:false,hint:false,ratingId:null,work:{}};save();navigate('practice');}
function move(index){const s=state.session;if(!s||index<0||index>=s.ids.length||index===s.index)return;flushDraft();pause();rememberQuestion();const work=s.work[s.ids[index]]||{};Object.assign(s,{index,startedAt:null,...cleanWork(work,s.ids[index],state.records)});save();render();window.scrollTo({top:0});document.querySelector('.exercise-heading h1')?.focus({preventScroll:true});}
function clockText(seconds){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function practice(){const s=state.session;if(!s){navigate('bank');return;}const q=byId[s.ids[s.index]];const r=s.ratingId?state.records.find(r=>r.id===s.ratingId):null;const favorite=state.favorites.includes(q.id);
 shell(`<div class="practice-layout"><aside class="paper question-rail"><div class="rail-title">${esc(s.mode)}${s.day?' / 第'+s.day+'天':''}</div><div class="rail-ids">${s.ids.map((id,i)=>{const rec=s.day?dayRecord(id,s.day):latest(id);return `<button class="qchip ${rec?gradeClass(rec.rating):''} ${i===s.index?'current':''}" data-action="jump" data-index="${i}" ${i===s.index?'aria-current="step"':''} title="${esc(byId[id].title)}">${id}</button>`;}).join('')}</div><div class="rail-note">绿色：会做<br>浅棕：不熟　浅红：不会<br>每题对照解答后自行评估。</div><div class="rail-progress">本组已评 ${s.ids.filter(id=>s.work?.[id]?.ratingId).length}/${s.ids.length}</div></aside><div class="exercise"><div class="exercise-top"><button class="btn flat" data-action="back">返回${s.day?'计划':'题库'}</button><div class="clock"><span id="timer" aria-label="本题用时">${clockText(elapsed())}</span><button data-action="timer">${s.startedAt?'暂停计时':'开始计时'}</button></div></div>${readingBar()}<article class="paper exercise-paper"><div class="exercise-meta"><span class="q-id">${q.id}</span><span>${q.subjectName}</span><span>第${q.group}组</span><span>建议${q.minutes}分钟</span><span>${q.kind}</span></div><div class="exercise-heading"><h1 tabindex="-1" id="question-heading">${esc(q.title)}</h1><button class="star ${favorite?'on':''}" data-action="favorite" data-id="${q.id}" aria-label="${favorite?'取消收藏':'收藏'} ${q.id}" aria-pressed="${favorite}">${favorite?'★':'☆'}</button></div><div class="rich prompt" id="question-prompt">${q.prompt_html}</div><section class="writing" id="my-writing"><div class="writing-head"><label for="draft">我的作答</label><span class="saved-label" id="draft-status">${state.drafts[q.id]?'草稿已保存':'边写边保存'}</span></div><textarea id="draft" maxlength="100000" placeholder="写下模型条件、推导步骤或论述提纲；也可以在纸上作答后回来对照。">${esc(state.drafts[q.id]||'')}</textarea><p class="writing-note">支持在纸上完整作答。系统不自动判分，请对照完整解答后自评。</p></section><div class="exercise-buttons"><button class="btn" data-action="hint" aria-expanded="${s.hint}">${s.hint?'收起提纲':'给我一点提示'}</button><button class="btn primary" data-action="reveal" aria-expanded="${s.revealed}">${s.revealed?'收起完整解答':'作答结束，核对解答'}</button></div>${s.hint&&!s.revealed?`<section class="hint-box"><h2>作答提纲</h2><div class="rich">${q.outline_html}</div></section>`:''}${s.revealed?`<section class="answer-section" id="answer"><div class="answer-nav"><button data-action="read-question">回看题目</button><button data-action="read-draft">对照我的作答</button></div><span class="answer-label">对照自己的推导与论证</span><h2>作答提纲</h2><div class="rich">${q.outline_html}</div><h2>完整解答</h2><div class="rich layered-answer">${q.answer_html}</div><div class="pitfalls"><h3>条件与易错</h3><div class="rich">${q.pitfalls_html}</div></div><section class="self-check"><h3>这道题，你掌握了吗？</h3><p>选择后保存本次作答。“不熟”和“不会”自动进入错题复做；可修改本次自评。</p><div class="rating-buttons">${[[0,'不会，需重做','bad'],[1,'不熟，有断点','medium'],[2,'会做，已掌握','']].map(([n,t,c])=>`<button class="rating ${c} ${r?.rating===n?'selected':''}" data-action="rate" data-rating="${n}" aria-pressed="${r?.rating===n}">${t}</button>`).join('')}</div>${r?`<p style="margin:12px 0 0">本次已记录：${gradeText(r.rating)}。${s.day?'已计入第'+s.day+'天的对应题目。':'本次为自由练习。'}</p><button class="btn primary rating-next" data-action="next">${s.index===s.ids.length-1?'完成本组，查看记录':'已保存，下一题'}</button>`:''}</section></section>`:''}<details class="source"><summary>题源与材料说明</summary>${q.source_refs.map(ref=>`<p>${esc(ref.exam_id)}<br>${esc(ref.source.split('/').pop())}，PDF物理页 ${esc(ref.pages)}。<br>${esc(ref.note)}</p>`).join('')}<p>本题为${q.kind}，参数与条件以本题为准。来源原PDF请在本地资料中查阅。</p></details></article><div class="exercise-bottom"><button class="btn" data-action="prev" ${s.index===0?'disabled':''}>上一题</button><span>第 ${s.index+1} / ${s.ids.length} 题</span><button class="btn ink" data-action="next">${s.index===s.ids.length-1?'结束本组':'下一题'}</button></div></div></div>`,'practice');
}
function materials(){shell(`<div class="page-heading"><div><h1>需要时，回来查一页。</h1><p>基础、公式和背诵与主线训练分开。这里保留打印版资料，方便在作答后回查。</p></div></div><div class="material-list">${D.materials.map(m=>`<section class="paper material"><span class="material-tag">${esc(m.tag)}</span><h2>${esc(m.title)}</h2><p>${esc(m.description)}</p><div class="actions">${m.files.map(f=>`<a class="btn ${f.label==='打开PDF'?'primary':''}" href="${f.url}" target="_blank" rel="noopener">${esc(f.label)}</a>`).join('')}</div></section>`).join('')}</div><p class="small muted" style="margin-top:24px">题目采用真题结构改编、条件变式与综合模拟；来源信息见每题底部。网站未改写题库正文。</p>`,'materials');}
let historyPage=1;
function history(){const records=[...state.records].reverse();historyPage=Math.min(historyPage,Math.max(1,Math.ceil(records.length/30)));shell(`<div class="page-heading"><div><h1>每一次作答，都留一笔。</h1><p>这里记录自评与本题计时。只查看答案不会计入已作答。点击题号可以复习该题。</p></div><button class="btn" data-action="export">导出全部记录</button></div><div class="stats-inline"><span><strong>${records.length}</strong>次作答</span><span><strong>${new Set(records.map(r=>r.qid)).size}</strong>道独立题</span><span><strong>${Math.round(records.reduce((a,r)=>a+r.seconds,0)/60)}</strong>分钟计时</span></div><section class="paper table-wrap">${records.length?`<table class="record-table"><thead><tr><th>题号</th><th>题目</th><th>自评</th><th>安排</th><th>用时</th><th>时间</th></tr></thead><tbody>${records.slice((historyPage-1)*30,historyPage*30).map(r=>`<tr><td><button data-action="single" data-id="${r.qid}" style="color:var(--green)">${r.qid}</button></td><td>${esc(byId[r.qid].title)}</td><td>${gradeText(r.rating)}</td><td>${r.day?'第'+r.day+'天':'自由练习'}</td><td>${clockText(r.seconds)}</td><td>${new Date(r.at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><h2>还没有完成的练习</h2><p>做一道题，对照答案后选择自评，这里就会留下记录。</p><a class="btn primary" href="#today">开始今日练习</a></div>'}</section>${records.length>30?`<div class="pagination"><button class="btn" data-action="history-prev" ${historyPage===1?'disabled':''}>上一页</button><span>${historyPage}/${Math.ceil(records.length/30)}</span><button class="btn" data-action="history-next" ${historyPage*30>=records.length?'disabled':''}>下一页</button></div>`:''}`,'history');}
function settings(){shell(`<div class="page-heading"><div><h1>让计划跟着你的节奏。</h1><p>题库固定，开始日期可调。记录只保存在当前设备的当前浏览器，不会自动同步。</p></div></div><section class="paper settings-panel"><h2>50天计划</h2><p>每科100题，五轮完整作答，每天每科10道。日均建议约11.4小时，含60分钟订正，休息另计。调整开始日期只移动日历，不改动已有练习记录。</p><div class="settings-row"><label for="start-date">开始日期</label><input type="date" id="start-date" value="${state.start}" min="2020-01-01" max="2100-12-31"><button class="btn primary" data-action="save-date">保存日期</button></div><p class="small" style="margin-top:14px">结束日期：${dateFor(50)}。当前选择第${selectedDay}天。</p></section><section class="paper settings-panel"><h2>备份与换设备</h2><p>导出文件包含作答草稿、自评、错题、收藏和计划日期。换设备或换浏览器后导入即可继续。导入时合并练习记录、收藏与草稿，同一条记录不重复计数；导入草稿会覆盖同题当前草稿。</p><div class="actions"><button class="btn primary" data-action="export">导出进度备份</button><button class="btn" data-action="import">导入备份</button><input type="file" id="import-file" accept="application/json,.json" class="visually-hidden" tabindex="-1"></div><p class="small" style="margin-top:15px">当前 ${state.records.length}次作答，${Object.values(state.drafts).filter(Boolean).length}份草稿，${state.favorites.length}道收藏。建议定期导出。</p></section><section class="paper settings-panel"><h2>练习方式</h2><p>计算与论述题由你对照解答自行评估。“会做”表示最近一次自评已掌握；“不熟”和“不会”进入错题复做。自由练习不自动补记计划日，避免把前一轮作答算作下一轮完成。</p><p>题库含三科各100道独立题。所有题干、提纲、完整解答、条件与易错均来自本轮已交付题库，网页只改变呈现方式。</p></section>`,'settings');}
function render(){const p=route();if(p==='practice')practice();else if(p==='today')home();else if(['bank','wrong','favorites'].includes(p))library(p);else if(p==='materials')materials();else if(p==='history')history();else settings();}
function exportData(){flushDraft();pause();const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`802练习进度-${nowDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('备份已导出，包含草稿与练习记录');render();}
function confirmImport(imported,total){return new Promise(resolve=>{
 const dialog=document.createElement('dialog');dialog.className='import-dialog';dialog.setAttribute('aria-labelledby','import-heading');
 dialog.innerHTML=`<h2 id="import-heading">确认合并备份</h2><p>合并后共有 <strong>${total}</strong> 次作答。同一条记录按最近修改保留，收藏取并集。</p><p>备份含 ${Object.values(imported.drafts).filter(Boolean).length} 份草稿；同题当前草稿将以备份为准。计划开始日期将改为 ${esc(imported.start)}。</p><p class="muted small">取消不会改动当前记录。建议先导出一份当前备份。</p><form method="dialog" class="actions"><button class="btn" value="cancel">取消</button><button class="btn primary" value="merge">合并导入</button></form>`;
 dialog.addEventListener('close',()=>{const accepted=dialog.returnValue==='merge';dialog.remove();resolve(accepted);},{once:true});document.body.append(dialog);dialog.showModal();
});}
async function importData(file){if(!file)return;if(file.size>12*1024*1024){toast('文件过大，请选择本网站导出的备份');return;}try{const imported=validate(JSON.parse(await file.text()));flushDraft();pause();const records=new Map(state.records.map(r=>[r.id,r]));for(const r of imported.records){const previous=records.get(r.id);if(!previous||(r.updatedAt||r.at)>(previous.updatedAt||previous.at))records.set(r.id,r);}if(records.size>20000)throw new Error('合并后记录过多，未导入。');if(!await confirmImport(imported,records.size))return;state={...state,start:imported.start,records:[...records.values()].sort((a,b)=>a.at-b.at),drafts:{...state.drafts,...imported.drafts},favorites:[...new Set([...state.favorites,...imported.favorites])],session:state.session||imported.session,reading:imported.reading};save();selectedDay=todayDay();render();toast(`已合并备份，共${state.records.length}次作答`);}catch(e){toast(e.message||'无法读取备份，原记录未改动');}}
root.addEventListener('input',e=>{if(e.target.id==='draft'){const s=state.session;if(s){state.drafts[s.ids[s.index]]=e.target.value;save();document.getElementById('draft-status').textContent=storageOK?'草稿已保存':'未能保存，请导出备份';}}if(e.target.id==='search'&&!e.isComposing){filter.search=e.target.value;filter.page=1;const pos=e.target.selectionStart;library(route());const el=document.getElementById('search');el.focus();try{el.setSelectionRange(pos,pos);}catch{}}});
root.addEventListener('compositionend',e=>{if(e.target.id==='search')e.target.dispatchEvent(new Event('input',{bubbles:true}));});
root.addEventListener('change',e=>{if(e.target.id==='reading-face'){state.reading.face=e.target.value==='sans'?'sans':'serif';save();applyReading();}if(e.target.id==='day-select'){selectedDay=Number(e.target.value);home();}if(e.target.id==='group-filter'){filter.group=e.target.value;filter.page=1;library(route());}if(e.target.id==='status-filter'){filter.status=e.target.value;filter.page=1;library(route());}if(e.target.id==='import-file'){const file=e.target.files[0];e.target.value='';importData(file);}});
root.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,s=state.session;
 if(a==='font-size'){flushDraft();state.reading.size=Number(b.dataset.size);save();applyReading();for(const button of root.querySelectorAll('[data-action="font-size"]')){const selected=Number(button.dataset.size)===state.reading.size;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));}}
 if(a==='focus'){flushDraft();state.reading.focus=!state.reading.focus;save();applyReading();b.textContent=state.reading.focus?'退出专注':'专注阅读';b.setAttribute('aria-pressed',String(state.reading.focus));}
 if(a==='read-question')readingLocation('question-heading');
 if(a==='read-draft')readingLocation('my-writing');
 if(a==='day-prev'||a==='day-next'){selectedDay=Math.max(1,Math.min(50,selectedDay+(a==='day-next'?1:-1)));home();}
 if(a==='today'){selectedDay=todayDay();home();}
 if(a==='resume')navigate('practice');
 if(a==='start-day'||a==='day-question'){const ids=D.plan.days[selectedDay-1][b.dataset.sub+'_refs'];const index=a==='day-question'?ids.indexOf(b.dataset.id):Math.max(0,ids.findIndex(id=>!dayRecord(id,selectedDay)));start(ids,sub[b.dataset.sub].name+'每日10题',selectedDay,index);}
 if(a==='subject'){filter={...filter,subject:b.dataset.sub,group:'all',page:1};library(route());}
 if(a==='favorite'){flushDraft();const id=b.dataset.id;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();toast(state.favorites.includes(id)?'已收藏':'已取消收藏');}
 if(a==='single')start([b.dataset.id],'自由练习');
 if(a==='clear-filter'){filter={...filter,group:'all',status:'all',search:'',page:1};library(route());}
 if(a==='start-filter'||a==='random'){let ids=filtered(route()).map(q=>q.id);if(a==='random'){for(let i=ids.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]];}ids=ids.slice(0,10);}if(ids.length)start(ids,sub[filter.subject].name+(a==='random'?'随机10题':'专题练习'));}
 if(a==='prev-page'||a==='next-page'){filter.page+=a==='next-page'?1:-1;library(route());window.scrollTo({top:0});}
 if(a==='jump')move(Number(b.dataset.index));
 if(a==='prev')move(s.index-1);
 if(a==='next'){if(s.index<s.ids.length-1)move(s.index+1);else{navigate(s.day?'today':'history');toast('本组练习已结束，未自评的题不计完成');}}
 if(a==='back')navigate(s.day?'today':'bank');
 if(a==='timer'){flushDraft();if(s.startedAt)pause();else{s.startedAt=Date.now();save();}practice();}
 if(a==='hint'){flushDraft();s.hint=!s.hint;save();practice();}
 if(a==='reveal'){flushDraft();pause();s.revealed=!s.revealed;save();practice();if(s.revealed)readingLocation('answer');else readingLocation('my-writing');}
 if(a==='rate'&&s?.revealed){flushDraft();pause();let r=s.ratingId?state.records.find(r=>r.id===s.ratingId):null;if(!r){r={id:uid(),qid:s.ids[s.index],day:s.day,at:Date.now(),updatedAt:Date.now(),seconds:elapsed(),rating:Number(b.dataset.rating)};state.records.push(r);s.ratingId=r.id;}else{r.rating=Number(b.dataset.rating);r.updatedAt=Date.now();}save();practice();document.querySelector('.self-check')?.scrollIntoView({block:'center'});toast('已记录：'+gradeText(r.rating));}
 if(a==='save-date'){const value=document.getElementById('start-date').value;if(!validDate(value)||value<'2020-01-01'||value>'2100-12-31'){toast('请选择2020至2100年之间的有效日期');return;}state.start=value;selectedDay=todayDay();save();settings();toast('计划日期已更新，练习记录保留');}
 if(a==='export')exportData();
 if(a==='import')document.getElementById('import-file').click();
 if(a==='history-prev'||a==='history-next'){historyPage+=a==='history-next'?1:-1;history();}
});
window.addEventListener('hashchange',()=>{pause();render();window.scrollTo({top:0});});
document.addEventListener('visibilitychange',()=>{if(document.hidden){flushDraft();pause();}else if(route()==='practice')practice();});
window.addEventListener('beforeunload',()=>{flushDraft();pause();});
setInterval(()=>{const el=document.getElementById('timer');if(el)el.textContent=clockText(elapsed());},1000);
render();
})();
